namespace sv_8d8d0ad7306a48b9ad47c343aa6de7ce.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@using sv_8d8d0ad7306a48b9ad47c343aa6de7ce.Services

<div class="message-item @(IsHovered ? "hovered" : "")"
     @onmouseenter="() => IsHovered = true"
     @onmouseleave="OnMouseLeave">

    <div class="message-header">
        <span class="message-author">@Message.Author</span>
        <span class="message-time">@FormatRelativeTime(Message.SentAt)</span>
    </div>

    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="message-reactions">
            @foreach (var reaction in Message.Reactions)
            {
                <button class="reaction-badge" @onclick="() => OnReact.InvokeAsync(reaction.Emoji)">
                    <span>@reaction.Emoji</span>
                    <span class="reaction-count">@reaction.Users.Count</span>
                </button>
            }
        </div>
    }

    @if (ReplyCount > 0)
    {
        <button class="thread-link" @onclick="() => OnOpenThread.InvokeAsync()">
            @ReplyCount replies
        </button>
    }

    @if (IsHovered)
    {
        <div class="message-actions">
            <button class="action-btn" title="Reply" @onclick="() => OnOpenThread.InvokeAsync()">💬</button>
            <button class="action-btn" title="React" @onclick="ToggleEmojiPicker">😀</button>
        </div>

        @if (ShowEmojiPicker)
        {
            <div class="emoji-picker">
                @foreach (var emoji in CommonEmojis)
                {
                    <button class="emoji-option" @onclick="() => SelectEmoji(emoji)">@emoji</button>
                }
            </div>
        }
    }
</div>

@code {
    [Parameter, EditorRequired] public Message Message { get; set; } = default!;
    [Parameter] public int ReplyCount { get; set; }
    [Parameter] public EventCallback OnOpenThread { get; set; }
    [Parameter] public EventCallback<string> OnReact { get; set; }

    private bool IsHovered;
    private bool ShowEmojiPicker;

    private static readonly string[] CommonEmojis = ["👍", "❤️", "😂", "🎉", "🚀", "👀"];

    private void OnMouseLeave()
    {
        IsHovered = false;
        ShowEmojiPicker = false;
    }

    private void ToggleEmojiPicker() => ShowEmojiPicker = !ShowEmojiPicker;

    private async Task SelectEmoji(string emoji)
    {
        ShowEmojiPicker = false;
        await OnReact.InvokeAsync(emoji);
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

@using sv_8d8d0ad7306a48b9ad47c343aa6de7ce.Services

<div class="channel-list">
    <h3 class="channel-list-header">Channels</h3>

    @foreach (var channel in Channels)
    {
        <button class="channel-item @(channel.Id == SelectedChannelId ? "active" : "")"
                @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
            <div class="channel-name"># @channel.Name</div>
            <div class="channel-description">@TruncateDescription(channel.Description)</div>
            @if (channel.UnreadCount > 0)
            {
                <span class="unread-badge">@channel.UnreadCount</span>
            }
        </button>
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int SelectedChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }

    private static string TruncateDescription(string description)
    {
        return description.Length > 40 ? description[..37] + "..." : description;
    }
}

@using sv_8d8d0ad7306a48b9ad47c343aa6de7ce.Services

<div class="message-area">
    <div class="message-area-header">
        <h2># @ChannelName</h2>
        <p>@ChannelDescription</p>
    </div>

    <div class="message-list" @onscroll="HandleScroll" @ref="_messageListRef">
        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages...</div>
        }

        @foreach (var message in Messages)
        {
            @if (message.ReplyToId is null)
            {
                <MessageItem Message="message"
                             ReplyCount="GetReplyCount(message.Id)"
                             OnOpenThread="() => OnOpenThread.InvokeAsync(message.Id)"
                             OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
            }
        }
    </div>

    <div class="message-input-area">
        <textarea class="message-input" @bind="NewMessageText" @bind:event="oninput"
                  placeholder="Type a message..." @onkeydown="HandleKeyDown"></textarea>
        <button class="send-btn" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(NewMessageText)">
            Send
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = new();
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private ElementReference _messageListRef;
    private string NewMessageText = "";

    private int GetReplyCount(int messageId)
    {
        return ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;
    }

    private async Task HandleScroll()
    {
        // Scroll-to-top triggers loading older messages
        // JS interop would be needed for scroll position detection in production;
        // here we provide the callback for the parent to wire up
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessage();
        }
    }

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(NewMessageText)) return;
        var text = NewMessageText;
        NewMessageText = "";
        await OnSendMessage.InvokeAsync(text);
    }
}

@using sv_8d8d0ad7306a48b9ad47c343aa6de7ce.Services

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-message">
            <span class="message-author">@RootMessage.Author</span>
            <p class="message-content">@RootMessage.Content</p>
        </div>

        <div class="thread-replies">
            @foreach (var reply in ThreadMessages)
            {
                <div class="thread-reply">
                    <div class="message-header">
                        <span class="message-author">@reply.Author</span>
                        <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                    </div>
                    <div class="message-content">@reply.Content</div>
                </div>
            }
        </div>

        <div class="thread-input-area">
            <textarea class="message-input" @bind="ReplyText" @bind:event="oninput"
                      placeholder="Reply in thread..." @onkeydown="HandleKeyDown"></textarea>
            <button class="send-btn" @onclick="SendReply" disabled="@string.IsNullOrWhiteSpace(ReplyText)">
                Reply
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public Message? RootMessage { get; set; }
    [Parameter, EditorRequired] public List<Message> ThreadMessages { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnReply { get; set; }

    private string ReplyText = "";

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendReply();
        }
    }

    private async Task SendReply()
    {
        if (string.IsNullOrWhiteSpace(ReplyText)) return;
        var text = ReplyText;
        ReplyText = "";
        await OnReply.InvokeAsync(text);
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

@page "/chat"
@using sv_8d8d0ad7306a48b9ad47c343aa6de7ce.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(IsThreadOpen ? "thread-open" : "")">
    <div class="chat-sidebar">
        <ChannelList Channels="_channels"
                     SelectedChannelId="_selectedChannelId"
                     OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main">
        <MessageArea ChannelName="@_currentChannelName"
                     ChannelDescription="@_currentChannelDescription"
                     Messages="_messages"
                     ThreadReplyCounts="_threadReplyCounts"
                     IsLoadingMore="_isLoadingMore"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSendMessage="SendMessage"
                     OnLoadMore="LoadOlderMessages" />
    </div>

    @if (IsThreadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         ThreadMessages="_threadMessages"
                         OnClose="CloseThread"
                         OnReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<Message> _threadMessages = [];
    private Dictionary<int, int> _threadReplyCounts = new();
    private Message? _threadRootMessage;
    private int _selectedChannelId;
    private string _currentChannelName = "";
    private string _currentChannelDescription = "";
    private bool _isLoadingMore;
    private int _activeThreadRootId;

    private const int PageSize = 30;

    private bool IsThreadOpen => _threadRootMessage is not null;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _selectedChannelId = channelId;
        var channel = _channels.FirstOrDefault(c => c.Id == channelId);
        _currentChannelName = channel?.Name ?? "";
        _currentChannelDescription = channel?.Description ?? "";

        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channelId);
        ComputeThreadReplyCounts();

        // Close thread if switching channels
        _threadRootMessage = null;
        _threadMessages = [];
    }

    private async Task LoadOlderMessages()
    {
        if (_isLoadingMore) return;
        _isLoadingMore = true;

        var olderMessages = await ChatService.GetMessagesAsync(_selectedChannelId, _messages.Count, PageSize);
        if (olderMessages.Count > 0)
        {
            _messages.InsertRange(0, olderMessages);
            ComputeThreadReplyCounts();
        }

        _isLoadingMore = false;
    }

    private async Task OpenThread(int rootMessageId)
    {
        _activeThreadRootId = rootMessageId;
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
    }

    private void CloseThread()
    {
        _threadRootMessage = null;
        _threadMessages = [];
        _activeThreadRootId = 0;
    }

    private async Task SendMessage(string content)
    {
        var message = await ChatService.SendMessageAsync(_selectedChannelId, content, null);
        _messages.Add(message);
    }

    private async Task SendThreadReply(string content)
    {
        var reply = await ChatService.SendMessageAsync(_selectedChannelId, content, _activeThreadRootId);
        _threadMessages.Add(reply);

        // Update reply count
        _threadReplyCounts[_activeThreadRootId] =
            _threadReplyCounts.GetValueOrDefault(_activeThreadRootId) + 1;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistically update the local message
        var message = _messages.FirstOrDefault(m => m.Id == args.MessageId);
        if (message is not null)
        {
            var existing = message.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                message.Reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
        }
    }

    private void ComputeThreadReplyCounts()
    {
        _threadReplyCounts = _messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());
    }
}

