{"path": "/tmp/sv-8d8d0ad7306a48b9ad47c343aa6de7ce/Components/Pages/Chat/Chat.razor", "file_text": "@page "/chat"
@using sv_8d8d0ad7306a48b9ad47c343aa6de7ce.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(IsThreadOpen ? "thread-open" : "")">
    <div class="chat-sidebar">
        <ChannelList Channels="_channels"
                     SelectedChannelId="_selectedChannelId"
                     OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main">
        <MessageArea ChannelName="@_currentChannelName"
                     ChannelDescription="@_currentChannelDescription"
                     Messages="_messages"
                     ThreadReplyCounts="_threadReplyCounts"
                     IsLoadingMore="_isLoadingMore"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSendMessage="SendMessage"
                     OnLoadMore="LoadOlderMessages" />
    </div>

    @if (IsThreadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         ThreadMessages="_threadMessages"
                         OnClose="CloseThread"
                         OnReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<Message> _threadMessages = [];
    private Dictionary<int, int> _threadReplyCounts = new();
    private Message? _threadRootMessage;
    private int _selectedChannelId;
    private string _currentChannelName = "";
    private string _currentChannelDescription = "";
    private bool _isLoadingMore;
    private int _activeThreadRootId;

    private const int PageSize = 30;

    private bool IsThreadOpen => _threadRootMessage is not null;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _selectedChannelId = channelId;
        var channel = _channels.FirstOrDefault(c => c.Id == channelId);
        _currentChannelName = channel?.Name ?? "";
        _currentChannelDescription = channel?.Description ?? "";

        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channelId);
        ComputeThreadReplyCounts();

        // Close thread if switching channels
        _threadRootMessage = null;
        _threadMessages = [];
    }

    private async Task LoadOlderMessages()
    {
        if (_isLoadingMore) return;
        _isLoadingMore = true;

        var olderMessages = await ChatService.GetMessagesAsync(_selectedChannelId, _messages.Count, PageSize);
        if (olderMessages.Count > 0)
        {
            _messages.InsertRange(0, olderMessages);
            ComputeThreadReplyCounts();
        }

        _isLoadingMore = false;
    }

    private async Task OpenThread(int rootMessageId)
    {
        _activeThreadRootId = rootMessageId;
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
    }

    private void CloseThread()
    {
        _threadRootMessage = null;
        _threadMessages = [];
        _activeThreadRootId = 0;
    }

    private async Task SendMessage(string content)
    {
        var message = await ChatService.SendMessageAsync(_selectedChannelId, content, null);
        _messages.Add(message);
    }

    private async Task SendThreadReply(string content)
    {
        var reply = await ChatService.SendMessageAsync(_selectedChannelId, content, _activeThreadRootId);
        _threadMessages.Add(reply);

        // Update reply count
        _threadReplyCounts[_activeThreadRootId] =
            _threadReplyCounts.GetValueOrDefault(_activeThreadRootId) + 1;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistically update the local message
        var message = _messages.FirstOrDefault(m => m.Id == args.MessageId);
        if (message is not null)
        {
            var existing = message.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                message.Reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
        }
    }

    private void ComputeThreadReplyCounts()
    {
        _threadReplyCounts = _messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());
    }
}
"}

